#include "linkedlist_module.h"
static void ensureSortedForUpdate(int d, int key, PatientList& work) { if (!hasSorted[d][key]) { cout << "(No saved sorted copy for " << DS_NAMES[d] << " by " << KEY_NAMES[key] << " - building one with insertion sort, not timed)\n"; sortedData[d][key].copyFrom(orig[d]); long c = 0; insertionSort(sortedData[d][key], key, c); hasSorted[d][key] = true; } work.copyFrom(sortedData[d][key]); }
void insertDeleteMenu() { while (true) { cout << "\n--- LINKED LIST INSERT / DELETE (temporary experiments) ---\n1. Insert into UNSORTED data\n2. Insert into SORTED data\n3. Delete from UNSORTED data\n4. Delete from SORTED data\n5. Back\n"; int c = askInt("Choice: ", 1, 5); if (c == 5) return; int d = pickDataset(false), key = pickKey(); bool sortedMode = (c == 2 || c == 4); PatientList work; if (sortedMode) ensureSortedForUpdate(d, key, work); else work.copyFrom(orig[d]); int before = work.size, pos = -1; long comps = 0; double us; bool ok = true; if (c <= 2) { Patient np = askNewPatient(); auto s = Clock::now(); pos = sortedMode ? lowerBound(work, key, np, comps) : work.size; work.insertAt(pos, np); auto e = Clock::now(); us = elapsedUs(s, e); } else { Patient probe = askProbe(key); auto s = Clock::now(); if (sortedMode) { int lb = lowerBound(work, key, probe, comps); comps++; if (lb < work.size && matchAt(work, lb, key, probe)) pos = lb; } else pos = findFirst(work, key, probe, comps); if (pos >= 0) work.removeAt(pos); else ok = false; auto e = Clock::now(); us = elapsedUs(s, e); } const char* op = (c <= 2) ? "Insert" : "Delete"; const char* algo = (c == 1) ? "Append" : (c == 2) ? "Ordered" : (c == 3) ? "Linear" : "Binary"; logResult("LinkedList", DS_NAMES[d], op, algo, KEY_NAMES[key], sortedMode ? "Sorted" : "Unsorted", us, comps, work.memoryBytes()); printUpdateReport(op, ok, before, work.size, pos, us, comps, work.memoryBytes()); } }
